package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_2 : Boolean;
    attribute manualFrozen : Boolean := false;
    attribute previousPressed : Boolean := false;
    attribute frozenDisplayValue : Integer := 0;
    attribute frozenPwmValue : Integer := 0;
    perform action tick {
      first start;
      then if ((io_2) and ((not previousPressed))) {
        first start;
        then assign manualFrozen := (not manualFrozen);
      }
      then if (not manualFrozen) {
        first start;
        then assign frozenDisplayValue := RealFunctions::floor(io_0);
        then assign frozenPwmValue := RealFunctions::floor(io_0);
      }
      then assign previousPressed := io_2;
    }
    out attribute io_1 : Real = (if manualFrozen ? frozenPwmValue else RealFunctions::floor(io_0));
    out attribute io_3 : Boolean = manualFrozen;
    out attribute io_4 : Integer = (if manualFrozen ? frozenDisplayValue else RealFunctions::floor(io_0));
  }
  part system : Controller;
}
